import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

// Throne of Aegis: a small, touch-friendly kingdom strategy game.
const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x91a28a);
scene.fog = new THREE.Fog(0x91a28a, 34, 86);
const camera = new THREE.OrthographicCamera(-25,25,18,-18,.1,150);
camera.position.set(31,39,34); camera.lookAt(0,0,0);
const renderer = new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight(0xe4eee0,0x59644b,2.1));
const sun = new THREE.DirectionalLight(0xffedc4,3.3); sun.position.set(-14,28,12); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-38; sun.shadow.camera.right=38; sun.shadow.camera.top=38; sun.shadow.camera.bottom=-38; sun.shadow.bias=-.0002; scene.add(sun);
const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});
const materials={grass:mat(0x68845b),grass2:mat(0x748e62),stone:mat(0x929184),stoneDark:mat(0x666a61),roof:mat(0x75463b),wood:mat(0x78583a),gold:mat(0xc5a75b),water:mat(0x638d8d,.3),field:mat(0xb69b56),leaf:mat(0x3e6445),leaf2:mat(0x56794a),red:mat(0x9c5145),cloth:mat(0x496b7b)};
const world=new THREE.Group(); scene.add(world);
const pickables=[];
function mesh(geometry,material,x,y,z,parent=world,cast=true){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m;}
function block(x,y,z,sx,sy,sz,material,parent=world){return mesh(new THREE.BoxGeometry(sx,sy,sz),material,x,y,z,parent);}
function cylinder(x,y,z,r1,r2,h,material,parent=world,segments=8){return mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material,x,y,z,parent);}
function group(x=0,z=0){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);return g;}
function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h,false);const aspect=w/h;const viewH=aspect<.85?42:aspect<1.35?36:31;camera.left=-viewH*aspect/2;camera.right=viewH*aspect/2;camera.top=viewH/2;camera.bottom=-viewH/2;camera.updateProjectionMatrix();}
addEventListener('resize',resize);resize();

// A softly undulating, color-varied meadow and winding river.
const groundGeo=new THREE.PlaneGeometry(72,62,70,62);groundGeo.rotateX(-Math.PI/2);
const pos=groundGeo.attributes.position;const colors=[];const c1=new THREE.Color(0x68815c),c2=new THREE.Color(0x819267),c3=new THREE.Color(0x536e54);
for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i);let n=Math.sin(x*.31)*Math.cos(z*.27)*.11+Math.sin((x+z)*.12)*.08;pos.setY(i,n);let col=c1.clone().lerp(c2,Math.max(0,Math.sin(x*.16+z*.13)*.25+.08));if((Math.sin(x*.9+z*.4)*Math.cos(z*.83))>.89)col.lerp(c3,.32);colors.push(col.r,col.g,col.b)}
groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));const ground=mesh(groundGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}),0,-.24,0,world,false);
const river=mesh(new THREE.ShapeGeometry(new THREE.Shape().setFromPoints([new THREE.Vector2(-36,8),new THREE.Vector2(-27,4),new THREE.Vector2(-20,5),new THREE.Vector2(-13,2),new THREE.Vector2(-6,4),new THREE.Vector2(2,1),new THREE.Vector2(12,4),new THREE.Vector2(22,1),new THREE.Vector2(36,3),new THREE.Vector2(36,7),new THREE.Vector2(22,5),new THREE.Vector2(12,8),new THREE.Vector2(2,5),new THREE.Vector2(-6,8),new THREE.Vector2(-13,5),new THREE.Vector2(-20,8),new THREE.Vector2(-27,7),new THREE.Vector2(-36,11)])),materials.water,0,-.04,0,world,false);river.rotation.x=-Math.PI/2;river.position.y=-.12;
// Pebbled river bank / roads.
const roadMat=mat(0x9a8b68);const road=mesh(new THREE.ShapeGeometry(new THREE.Shape().setFromPoints([new THREE.Vector2(-24,17),new THREE.Vector2(-20,15),new THREE.Vector2(-11,9),new THREE.Vector2(-4,5),new THREE.Vector2(-1,5),new THREE.Vector2(-8,11),new THREE.Vector2(-17,17),new THREE.Vector2(-22,19)])),roadMat,0,-.02,0,world,false);road.rotation.x=-Math.PI/2;

function tree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);cylinder(0,.65*scale,0,.18*scale,.24*scale,1.3*scale,materials.wood,g,7);for(let i=0;i<3;i++){const r=(.8-i*.13)*scale;const leaf=cylinder(0,(1.5+i*.52)*scale,0,0,r,1.2*scale,i===1?materials.leaf2:materials.leaf,g,7);leaf.rotation.y=i*.4;}return g;}
function rock(x,z,s=1){const m=mesh(new THREE.DodecahedronGeometry(s,0),materials.stone,x,.28*s,z);m.scale.y=.65;m.rotation.set(.2,x*.1,z*.1);return m;}
for(const [x,z,s] of [[-18,-13,1.3],[-15,-14,.9],[-20,-9,1.2],[-13,-12,.8],[18,-14,1.1],[21,-12,.8],[23,-7,1.3],[17,-10,.9],[-20,14,.9],[-17,17,1.2],[23,14,1],[19,17,.8],[10,-17,1.2],[-8,-18,.9]])tree(x,z,s);
for(const [x,z,s] of [[-24,-5,.9],[-22,-7,.6],[24,9,.8],[26,7,.6],[8,16,.7],[-10,15,.8],[15,-4,.5]])rock(x,z,s);

// Castle masonry: crenellated curtain wall, corner towers, gatehouse and royal keep.
const fortress=group(-3,-2);const wallMat=materials.stone;const towerPositions=[[-5,-4],[5,-4],[-5,4],[5,4]];
