const state={food:180,gold:260,stone:145,iron:85,morale:82,fort:100,territories:0,units:{Infanteri:5,Pemanah:3,Kavaleri:1},buildings:{farm:2,mine:1,market:1,wall:1,tower:0,barracks:1,granary:0,academy:0,moat:0,trap:0},castleLevel:2,arch:0,mil:0,raid:null,selectedTab:'build',elapsed:0,lastTick:performance.now(),gameOver:false,zoom:1,panX:0,panZ:0};
const costs={farm:{food:30,wood:0,stone:15},mine:{gold:45,stone:20},market:{gold:75,stone:30},wall:{stone:55,gold:20},tower:{stone:60,gold:35},barracks:{stone:45,gold:50},granary:{wood:0,stone:35,gold:25},academy:{stone:70,gold:80},moat:{stone:45,gold:20},trap:{iron:18,gold:12}};
const buildMeta=[['farm','Ladang gandum','Tambah +2 gandum / menit','🌾'],['mine','Tambang besi','Hasilkan emas dan besi','⛏'],['market','Pasar kerajaan','Perdagangan +3 emas / menit','⚖'],['wall','Tembok batu','Perkuat perimeter benteng','▤'],['tower','Menara pemanah','Serangan pertahanan lebih kuat','♜'],['barracks','Barak','Latih prajurit kerajaan','⚔'],['granary','Lumbung','Jaga cadangan pangan rakyat','▥'],['academy','Akademi','Buka riset strategi lanjutan','✧'],['moat','Parit pertahanan','Perlambat serangan musuh','〰'],['trap','Jebakan paku','Lukai penyerbu di gerbang','⌁']];
const $=s=>document.querySelector(s); const toastEl=$('#toast');let toastTimer;
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2300)}
function modal(title,body,action='Mengerti',callback=null){$('#modalTitle').textContent=title;$('#modalBody').textContent=body;$('#modalAction').textContent=action;$('#modal').classList.remove('hidden');$('#modalAction').onclick=()=>{ $('#modal').classList.add('hidden');callback?.()};}
function have(cost){return Object.entries(cost).every(([k,v])=>state[k]>=v)}
function pay(cost){if(!have(cost)){toast('Sumber daya belum cukup untuk tindakan itu.');return false}for(const [k,v] of Object.entries(cost))state[k]-=v;return true}
function costMarkup(cost){return Object.entries(cost).filter(([,v])=>v).map(([k,v])=>`<span>${({food:'✦',gold:'◈',stone:'⬟',iron:'◆',wood:'▰'})[k]} ${v}</span>`).join('')}
function updateHud(){for(const k of ['food','gold','stone','iron'])$(`#${k}`).textContent=Math.floor(state[k]);$('#morale-label').textContent=`${Math.round(state.morale)}%`;$('#morale-meter').style.width=`${state.morale}%`;$('#fort-label').textContent=`${Math.round(state.fort)}%`;$('#fort-meter').style.width=`${state.fort}%`;$('#territory-count').textContent=`${state.territories}/3`;
$('#wall-quest').textContent=`${Math.min(2,state.buildings.wall+state.buildings.tower)}/2`;$('#conquer-quest').textContent=`${state.territories}/3`;
$('#battle-title').textContent=state.raid?`Pertempuran berlangsung · ${state.raid.time}s`:'Lembah Aegis aman';$('#battle-copy').textContent=state.raid?'Musuh menyerbu gerbang! Aktifkan kemampuan khusus.':'Siapkan kerajaanmu untuk ancaman yang datang.';$('#battleBtn').innerHTML=state.raid?'BERTAHAN <span>⚔</span>':'SERANG PERBATASAN <span>→</span>';
$('#food-rate').textContent=`+${3+state.buildings.farm}/mnt`;$('#gold-rate').textContent=`+${2+state.buildings.mine+2*state.buildings.market}/mnt`;
}
function renderTab(tab=state.selectedTab){state.selectedTab=tab;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const content=$('#tab-content');content.className='tab-content';
if(tab==='build'){content.innerHTML='<div class="section-label">EKONOMI & INFRASTRUKTUR</div>'+buildMeta.map(([id,name,desc,icon])=>{const c=costs[id];return `<div class="build-card"><div class="build-icon">${icon}</div><div class="build-info"><b>${name}</b><small>${desc}</small><div class="costs">${costMarkup(c)}</div></div><button class="buy-btn" data-build="${id}" ${have(c)?'':'disabled'}>BANGUN</button></div>`}).join('');content.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>build(b.dataset.build));}
if(tab==='army'){const specs=[['Infanteri','⚔',45,20,'Garis depan tangguh'],['Pemanah','➶',35,24,'Pertahanan jarak jauh'],['Kavaleri','♞',65,35,'Serangan cepat']];content.innerHTML='<div class="section-label">GARNISUN BENTENG</div>'+specs.map(([name,icon,gold,food,desc])=>`<div class="unit-row"><div class="unit-emoji">${icon}</div><div><b>${name}</b><small>${desc} · ${state.units[name]} pasukan</small></div><button class="buy-btn" data-train="${name}" data-gold="${gold}" data-food="${food}">LATIH</button></div>`).join('')+`<div class="section-label" style="margin-top:16px">KEMAMPUAN PERTAHANAN</div><button class="card-action" id="arrowSkill" ${state.raid?'':'disabled'}>➶ Hujan Panah <span class="action-sub">Hujani penyerbu · biaya 25 emas</span></button><button class="card-action" id="oilSkill" ${state.raid?'':'disabled'}>♨ Minyak Mendidih <span class="action-sub">Hancurkan gelombang musuh · biaya 20 besi</span></button><button class="card-action" id="spySkill">◉ Kirim Pengintai <span class="action-sub">Ungkap kekuatan musuh · 18 emas</span></button>`;content.querySelectorAll('[data-train]').forEach(b=>b.onclick=()=>train(b.dataset.train,+b.dataset.gold,+b.dataset.food));$('#arrowSkill').onclick=()=>skill('arrow');$('#oilSkill').onclick=()=>skill('oil');$('#spySkill').onclick=()=>spy();}
if(tab==='research'){content.innerHTML='<div class="section-label">POHON TEKNOLOGI · CASTLE LV.'+state.castleLevel+'</div><div class="research-card"><b>🏰 Arsitektur Benteng ${state.arch?'I':''}</b><p>Perkuat dinding batu dan tingkatkan ketahanan kastil sebesar 20%.</p><div class="costs">◈ 90 &nbsp; ⬟ 65</div><button class="buy-btn" data-tech="arch" ${state.arch?'disabled':''}>${state.arch?'TELAH DITELITI':'TELITI'}</button></div><div class="research-card"><b>⚔ Taktik Militer ${state.mil?'I':''}</b><p>Latih pasukan profesional. Kekuatan serangan dan pertahanan meningkat.</p><div class="costs">◈ 110 &nbsp; ◆ 35</div><button class="buy-btn" data-tech="mil" ${state.mil?'disabled':''}>${state.mil?'TELAH DITELITI':'TELITI'}</button></div><div class="research-card"><b>♔ Tingkatkan Kastil · Lv. ${state.castleLevel}</b><p>Buka pengetahuan baru dan tambah moral rakyat.</p><div class="costs">◈ 150 &nbsp; ⬟ 100</div><button class="buy-btn" data-tech="castle" ${state.castleLevel>=4?'disabled':''}>TINGKATKAN</button></div>`;content.querySelectorAll('[data-tech]').forEach(b=>b.onclick=()=>research(b.dataset.tech));}
}
function build(type){const cost=costs[type];if(!pay(cost))return;state.buildings[type]++;if(type==='wall')state.fort=Math.min(100,state.fort+12);addBuildVisual(type);toast(`${buildMeta.find(x=>x[0]===type)[1]} berhasil dibangun.`);renderTab();updateHud();}
function train(name,gold,food){if(!pay({gold,food}))return;state.units[name]++;const color=name==='Kavaleri'?0xa8804e:name==='Pemanah'?0x668596:0x53785c;soldier((Math.random()-.5)*2,-10-Math.random()*1,color);toast(`${name} baru siap membela kerajaan.`);renderTab();}
function research(type){const costs={arch:{gold:90,stone:65},mil:{gold:110,iron:35},castle:{gold:150,stone:100}};if(!pay(costs[type]))return;if(type==='arch'){state.arch=1;state.fort=Math.min(100,state.fort+20)}else if(type==='mil')state.mil=1;else{state.castleLevel++;state.morale=Math.min(100,state.morale+8)}toast('Pengetahuan baru memperkuat kerajaanmu.');renderTab();updateHud();}
function spy(){if(!pay({gold:18}))return;const foe=state.territories;const power=[8,13,18][foe]||22;$('#intel-copy').textContent=`Musuh: ${power} kekuatan · peluang ${armyPower()>=power?'menang':'berat'}`;modal('Laporan Pengintai',`Pengintai melaporkan ${power} kekuatan musuh di wilayah berikutnya. Pasukanmu memiliki kekuatan ${armyPower()}. ${state.buildings.tower?'Menara pemanah memperkuat pertahanan benteng.':''}`);updateHud();}
function armyPower(){return state.units.Infanteri*2+state.units.Pemanah*2+state.units.Kavaleri*4+state.buildings.tower*3+state.arch*4+state.mil*7}
function startBattle(){if(state.gameOver)return;if(state.raid){useDefend();return}if(state.territories>=3){winGame();return}if(armyPower()<[8,13,18][state.territories]){modal('Pasukan belum siap','Latih pasukan atau teliti taktik militer sebelum menyerbu kerajaan tetangga. Kirim pengintai untuk mengetahui kekuatan lawan.');return}if(!pay({food:30}))return;state.raid={time:16,damage:0};scene.userData.enemyWave=true;for(let i=0;i<5+state.territories*2;i++){const s=soldier(10+Math.random()*5,-6+Math.random()*7,0x9c5145);s.userData.enemy=true;s.position.x+=13;}toast('Pasukan musuh terlihat! Bentengi gerbang!');renderTab('army');updateHud();}
function useDefend(){if(state.raid){state.raid.damage+=3;toast('Pasukan bergerak ke tembok pertahanan!')}}
function skill(type){if(!state.raid){toast('Kemampuan hanya dapat digunakan saat pertempuran.');return}const cost=type==='arrow'?{gold:25}:{iron:20};if(!pay(cost))return;const dmg=type==='arrow'?5:8;state.raid.damage+=dmg;toast(type==='arrow'?'Hujan panah menghantam barisan musuh!':'Minyak mendidih membakar para penyerbu!');for(const u of units)if(u.userData.enemy){u.visible=false}updateHud();renderTab('army')}
function resolveBattle(){const enemyPower=[8,13,18][state.territories]||22;const strength=armyPower()+state.raid.damage;const win=strength>=enemyPower;for(let i=units.length-1;i>=0;i--)if(units[i].userData.enemy){world.remove(units[i]);units.splice(i,1)}if(win){state.territories++;state.gold+=75;state.food+=35;state.morale=Math.min(100,state.morale+5);state.fort=Math.max(30,state.fort-(state.raid.damage?4:11));toast('Kemenangan! Wilayah baru bergabung dengan kerajaan.');if(state.territories>=3)setTimeout(winGame,900)}else{state.fort=Math.max(0,state.fort-27);state.morale=Math.max(10,state.morale-13);state.units.Infanteri=Math.max(1,state.units.Infanteri-1);toast('Gerbang retak! Tingkatkan pertahanan sebelum serangan berikutnya.')};state.raid=null;renderTab();updateHud();if(state.fort<=0)loseGame();}
function winGame(){state.gameOver=true;modal('Lembah telah disatukan','Tiga kerajaan tetangga kini bersumpah setia kepada Throne of Aegis. Bentengmu berdiri tegak, dan rakyat merayakan era baru perdamaian.','Mainkan lagi',()=>location.reload())}
function loseGame(){state.gameOver=true;modal('Benteng telah jatuh','Pertahanan kerajaan runtuh. Bangun kembali kekuatanmu dan coba satukan lembah sekali lagi.','Coba lagi',()=>location.reload())}
function tick(now){const dt=Math.min(.1,(now-state.lastTick)/1000);state.lastTick=now;state.elapsed+=dt;if(state.elapsed>5){state.elapsed=0;state.food+=.28+state.buildings.farm*.22;state.gold+=.2+state.buildings.mine*.12+state.buildings.market*.25;state.stone+=.12+state.buildings.mine*.1;state.iron+=.05+state.buildings.mine*.08;if(state.food<20)state.morale=Math.max(10,state.morale-.7);else if(state.morale<95)state.morale+=.15;if(state.morale<25&&Math.random()<.001){state.fort=Math.max(0,state.fort-4);toast('Kerusuhan rakyat melemahkan benteng!')}updateHud();if(document.querySelector('.right-rail:not(.hidden)'))renderTab(state.selectedTab)}if(state.raid){state.raid.time-=dt;if(state.raid.time<=0)resolveBattle();else if(Math.random()<dt*.55){state.raid.damage-=.1;state.fort=Math.max(0,state.fort-.13*(1-state.buildings.tower*.12));if(state.fort<=0)loseGame()}}for(const u of units){if(u.userData.enemy){u.position.x-=dt*.15;u.rotation.y=Math.sin(now*.004)*.1}else u.rotation.y=Math.sin(now*.002+u.position.x)*.04}renderer.render(scene,camera);requestAnimationFrame(tick)}requestAnimationFrame(tick);

