 function build(type){const cost=costs[type];if(!pay(cost))return;state.buildings[type]++;if(type==='wall')state.fort=Math.min(100,state.fort+12);addBuildVisual(type);toast(`${buildMeta.find(x=>x[0]===type)[1]} berhasil dibangun.`);renderTab();updateHud();}
 function train(name,gold,food){if(!pay({gold,food}))return;state.units[name]++;const color=name==='Kavaleri'?0xa8804e:name==='Pemanah'?0x668596:0x53785c;soldier((Math.random()-.5)*2,-10-Math.random()*1,color);toast(`${name} baru siap membela kerajaan.`);renderTab();}
 function research(type){const costs={arch:{gold:90,stone:65},mil:{gold:110,iron:35},castle:{gold:150,stone:100}};if(!pay(costs[type]))return;if(type==='arch'){state.arch=1;state.fort=Math.min(100,state.fort+20)}else if(type==='mil')state.mil=1;else{state.castleLevel++;state.morale=Math.min(100,state.morale+8)}toast('Pengetahuan baru memperkuat kerajaanmu.');renderTab();updateHud();}
